from threetears.evals import Eval

from change import change_for, load_drawer

def give_change(case):
    """The coins the till pays out for the sale, from a full float."""
    return {"change": change_for(case["total_pence"], case["tendered_pence"], load_drawer("data/float.json"))}


def as_paid_out(case, out):
    """The change is what the old till paid out."""
    return out["change"] == case["change"]

sales = Eval("data/till_log.jsonl", runner=give_change, grader=[as_paid_out], k=1)
